input.sparql:
SELECT ?s ?class ?label WHERE {
  ?s a ?class .
  FILTER(str(?class) CONTAINS "TemperatureSensor" || str("?class") CONTAINS "Zone")
  OPTIONAL { ?s rdfs:label ?label }
} LIMIT 100

SELECT ?s ?class ?label WHERE {
  ?s a ?class .
  OPTIONAL { ?s rdfs:label ?label }
  FILTER(str(?class) CONTAINS "Temperature" || ?class = brick:Zone)
} LIMIT 150

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?s ?class ?label WHERE {
  ?s a brick:Zone .
  OPTIONAL { ?s rdfs:label ?label }
} LIMIT 150

