input.sparql:
PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?zone ?zoneLabel ?sensor ?ref ?sid WHERE {
  { ?zone a brick:Room } UNION { ?zone a brick:HVAC_Zone }
  ?zone brick:hasPoint ?sensor .
  ?sensor a brick:Zone_Air_Temperature_Sensor .
  OPTIONAL { ?zone rdfs:label ?zoneLabel }
  ?sensor ref:hasExternalReference ?refx .
  ?refx ref:hasTimeseriesId ?sid .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?zone ?zoneLabel ?sensor ?sid WHERE {
  ?zone brick:hasPoint ?sensor .
  ?sensor a brick:Zone_Air_Temperature_Sensor .
  OPTIONAL { ?zone rdfs:label ?zoneLabel }
  OPTIONAL {
    ?sensor ref:hasExternalReference ?refx .
    ?refx ref:hasTimeseriesId ?sid .
  }
}
